17	import React, { Fragment, ReactElement } from 'react';
18	import {
19	  withStyles,
20	  createStyles,
21	  WithStyles,
22	  Theme,
23	} from '@material-ui/core/styles';
24	import startCase from 'lodash/startCase';
25	import Typography from '@material-ui/core/Typography';
26	
27	import {
28	  MetadataTable,
29	  MetadataTableItem,
30	  MetadataList,
31	  MetadataListItem,
32	} from './MetadataTable';
33	
34	export type StructuredMetadataTableListClassKey = 'root';
35	
36	const listStyle = createStyles({
37	  root: {
38	    margin: '0 0',
39	    listStyleType: 'none',
40	  },
41	});
42	
43	export type StructuredMetadataTableNestedListClassKey = 'root';
44	
45	const nestedListStyle = (theme: Theme) =>
46	  createStyles({
47	    root: {
48	      ...listStyle.root,
49	      paddingLeft: theme.spacing(1),
50	    },
51	  });
52	
53	interface StyleProps extends WithStyles {
54	  children?: React.ReactNode;
55	}
56	// Sub Components
57	const StyledList = withStyles(listStyle, {
58	  name: 'BackstageStructuredMetadataTableList',
59	})(({ classes, children }: StyleProps) => (
60	  <MetadataList classes={classes}>{children}</MetadataList>
61	));
62	const StyledNestedList = withStyles(nestedListStyle, {
63	  name: 'BackstageStructuredMetadataTableNestedList',
64	})(({ classes, children }: StyleProps) => (
65	  <MetadataList classes={classes}>{children}</MetadataList>
66	));
67	
68	function renderList(list: Array<any>, options: Options, nested: boolean) {
69	  const values = list.map((item: any, index: number) => (
70	    <MetadataListItem key={index}>
71	      {toValue(item, options, nested)}
72	    </MetadataListItem>
73	  ));
74	  return nested ? (
75	    <StyledNestedList>{values}</StyledNestedList>
76	  ) : (
77	    <StyledList>{values}</StyledList>
78	  );
79	}
80	
81	function renderMap(
82	  map: { [key: string]: any },
83	  options: Options,
84	  nested: boolean,
85	) {
86	  const values = Object.keys(map).map(key => {
87	    const value = toValue(map[key], options, true);
88	    return (
89	      <MetadataListItem key={key}>
90	        <Typography variant="body2" component="span">
91	          {`${options.titleFormat(key)}: `}
92	        </Typography>
93	        {value}
94	      </MetadataListItem>
95	    );
96	  });
97	
98	  return nested ? (
99	    <StyledNestedList>{values}</StyledNestedList>
100	  ) : (
101	    <StyledList>{values}</StyledList>
102	  );
103	}
104	
105	function toValue(
106	  value: ReactElement | object | Array<any> | boolean,
107	  options: Options,
108	  nested: boolean,
109	) {
110	  if (React.isValidElement(value)) {
111	    return <Fragment>{value}</Fragment>;
112	  }
113	
114	  if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
115	    return renderMap(value, options, nested);
116	  }
117	
118	  if (Array.isArray(value)) {
119	    return renderList(value, options, nested);
120	  }
121	
122	  if (typeof value === 'boolean') {
123	    return <Fragment>{value ? '✅' : '❌'}</Fragment>;
124	  }
125	
126	  return (
127	    <Typography variant="body2" component="span">
128	      {value}
129	    </Typography>
130	  );
131	}
132	const ItemValue = ({ value, options }: { value: any; options: Options }) => (
133	  <Fragment>{toValue(value, options, false)}</Fragment>
134	);
135	
136	const TableItem = ({
137	  title,
138	  value,
139	  options,
140	}: {
141	  title: string;
142	  value: any;
143	  options: Options;
144	}) => {
145	  return (
146	    <MetadataTableItem title={options.titleFormat(title)}>
147	      <ItemValue value={value} options={options} />
148	    </MetadataTableItem>
149	  );
150	};
151	
152	function mapToItems(info: { [key: string]: string }, options: Options) {
153	  return Object.keys(info).map(key => (
154	    <TableItem key={key} title={key} value={info[key]} options={options} />
155	  ));
156	}
157	
158	/** @public */
159	export interface StructuredMetadataTableProps {
160	  metadata: { [key: string]: any };
161	  dense?: boolean;
162	  options?: {
163	    /**
164	     * Function to format the keys from the `metadata` object. Defaults to
165	     * startCase from the lodash library.
166	     * @param key - A key within the `metadata`
167	     * @returns Formatted key
168	     */
169	    titleFormat?: (key: string) => string;
170	  };
171	}
172	
173	type Options = Required<NonNullable<StructuredMetadataTableProps['options']>>;
174	
175	/** @public */
176	export function StructuredMetadataTable(props: StructuredMetadataTableProps) {
177	  const { metadata, dense = true, options = {} } = props;
178	  const metadataItems = mapToItems(metadata, {
179	    titleFormat: startCase,
180	    ...options,
181	  });
182	  return <MetadataTable dense={dense}>{metadataItems}</MetadataTable>;
183	}
