17	import { render, within } from '@testing-library/react';
18	import { startCase } from 'lodash';
19	import React from 'react';
20	import { StructuredMetadataTable } from './StructuredMetadataTable';
21	
22	describe('<StructuredMetadataTable />', () => {
23	  it('renders without exploding', () => {
24	    const metadata = { hello: 'world', foo: null };
25	    const { getByText } = render(
26	      <StructuredMetadataTable metadata={metadata} />,
27	    );
28	    expect(getByText(metadata.hello)).toBeInTheDocument();
29	  });
30	
31	  describe('Item Mappings', () => {
32	    it('Iterates over and displays every field in the map', () => {
33	      const metadata = {
34	        field1: 'one',
35	        field2: 'two',
36	        field3: 'three',
37	      } as const;
38	      const { getByText } = render(
39	        <StructuredMetadataTable metadata={metadata} />,
40	      );
41	      for (const [key, value] of Object.entries(metadata)) {
42	        expect(getByText(startCase(key))).toBeInTheDocument();
43	        expect(getByText(value)).toBeInTheDocument();
44	      }
45	    });
46	
47	    it('Supports primitive value fields', () => {
48	      const metadata = { strField: 'my field', intField: 1 } as const;
49	      const { getByText } = render(
50	        <StructuredMetadataTable metadata={metadata} />,
51	      );
52	
53	      for (const [key, value] of Object.entries(metadata)) {
54	        expect(getByText(startCase(key))).toBeInTheDocument();
55	        expect(getByText(value.toString())).toBeInTheDocument();
56	      }
57	    });
58	
59	    it('Supports array fields', () => {
60	      const metadata = { arrayField: ['arrVal1', 'arrVal2'] } as const;
61	      const { getByText } = render(
62	        <StructuredMetadataTable metadata={metadata} />,
63	      );
64	      const keys = Object.keys(metadata);
65	      keys.forEach(value => {
66	        expect(getByText(startCase(value))).toBeInTheDocument();
67	      });
68	      metadata.arrayField.forEach(value => {
69	        expect(getByText(value)).toBeInTheDocument();
70	      });
71	    });
72	
73	    it('Supports boolean values', () => {
74	      const metadata = { foo: true, bar: false };
75	      const expectedValues = [
76	        ['Foo', '✅'],
77	        ['Bar', '❌'],
78	      ];
79	
80	      const { getAllByRole } = render(
81	        <StructuredMetadataTable metadata={metadata} />,
82	      );
83	
84	      getAllByRole('row').forEach((row, index) => {
85	        const [firstCell, secondCell] = within(row).getAllByRole('cell');
86	        const [expectedKey, expectedValue] = expectedValues[index];
87	
88	        expect(firstCell).toHaveTextContent(expectedKey);
89	        expect(secondCell).toHaveTextContent(expectedValue);
90	      });
91	    });
92	
93	    it('Supports react elements', () => {
94	      const metadata = { react: <div id="findMe"> field </div> };
95	      const { getByText } = render(
96	        <StructuredMetadataTable metadata={metadata} />,
97	      );
98	
99	      expect(getByText('field')).toBeInTheDocument();
100	    });
101	
102	    it('Supports object elements', () => {
103	      const metadata = {
104	        config: { a: 1, b: 2 },
105	      } as const;
106	      const { getByText } = render(
107	        <StructuredMetadataTable metadata={metadata} />,
108	      );
109	
110	      for (const [key, value] of Object.entries(metadata.config)) {
111	        expect(getByText(startCase(key), { exact: false })).toBeInTheDocument();
112	        expect(
113	          getByText(value.toString(), { exact: false }),
114	        ).toBeInTheDocument();
115	      }
116	    });
117	  });
118	
119	  describe('Title formatting', () => {
120	    const metadata = {
121	      testA: 'stuff',
122	      testB: { testC: 'stuff' },
123	      testD: [{ testE: 'stuff' }],
124	    };
125	
126	    it('should make keys human readable', async () => {
127	      const rendered = render(<StructuredMetadataTable metadata={metadata} />);
128	      expect(rendered.queryByText(/^Test A/)).toBeInTheDocument();
129	      expect(rendered.queryByText(/^Test B/)).toBeInTheDocument();
130	      expect(rendered.queryByText(/^Test C/)).toBeInTheDocument();
131	      expect(rendered.queryByText(/^Test D/)).toBeInTheDocument();
132	      expect(rendered.queryByText(/^Test E/)).toBeInTheDocument();
133	    });
134	
135	    it('should be possible to disable it', async () => {
136	      const rendered = render(
137	        <StructuredMetadataTable
138	          metadata={metadata}
139	          options={{ titleFormat: key => key }}
140	        />,
141	      );
142	      expect(rendered.queryByText(/^testA/)).toBeInTheDocument();
143	      expect(rendered.queryByText(/^testB/)).toBeInTheDocument();
144	      expect(rendered.queryByText(/^testC/)).toBeInTheDocument();
145	      expect(rendered.queryByText(/^testD/)).toBeInTheDocument();
146	      expect(rendered.queryByText(/^testE/)).toBeInTheDocument();
147	    });
148	
149	    it('should be customizable', async () => {
150	      const spongeBobCase = (key: string) =>
151	        key
152	          .split('')
153	          .map((letter, index) => {
154	            if (index % 2 === 0) {
155	              return letter.toLocaleLowerCase('en-US');
156	            }
157	            return letter.toLocaleUpperCase('en-US');
158	          })
159	          .join('');
160	
161	      const rendered = render(
162	        <StructuredMetadataTable
163	          metadata={metadata}
164	          options={{ titleFormat: spongeBobCase }}
165	        />,
166	      );
167	      expect(rendered.queryByText(/^tEsTa/)).toBeInTheDocument();
168	      expect(rendered.queryByText(/^tEsTb/)).toBeInTheDocument();
169	      expect(rendered.queryByText(/^tEsTc/)).toBeInTheDocument();
170	      expect(rendered.queryByText(/^tEsTd/)).toBeInTheDocument();
171	      expect(rendered.queryByText(/^tEsTe/)).toBeInTheDocument();
172	    });
173	  });
174	});
