46	        return {
47	          updateStrategy: statefulset.spec?.updateStrategy ?? '???',
48	          podManagementPolicy: statefulset.spec?.podManagementPolicy ?? '???',
49	          serviceName: statefulset.spec?.serviceName ?? '???',
