16	import { CodeSnippet } from '@backstage/core-components';
17	import FormControlLabel from '@material-ui/core/FormControlLabel';
18	import Switch from '@material-ui/core/Switch';
19	import jsyaml from 'js-yaml';
20	import React, { useState } from 'react';
21	
22	/**
23	 * Props of ManifestYaml
24	 *
25	 * @public
26	 */
27	export interface ManifestYamlProps {
28	  object: object;
29	}
30	
31	/**
32	 * Renders a Kubernetes object as a YAML code snippet
33	 *
34	 * @public
35	 */
36	export const ManifestYaml = ({ object }: ManifestYamlProps) => {
37	  // Toggle whether the Kubernetes resource managed fields should be shown in
38	  // the YAML display. This toggle is only available when the YAML is being
39	  // shown because managed fields are never visible in the structured display.
40	  const [managedFields, setManagedFields] = useState<boolean>(false);
41	  return (
42	    <>
43	      <FormControlLabel
44	        control={
45	          <Switch
46	            checked={managedFields}
47	            onChange={event => {
48	              setManagedFields(event.target.checked);
49	            }}
50	            name="Managed Fields"
51	          />
52	        }
53	        label="Managed Fields"
54	      />
55	      <CodeSnippet
56	        language="yaml"
57	        text={jsyaml.dump(object, {
58	          // NOTE: this will remove any field called `managedFields`
59	          // not just the metadata one
60	          // TODO: @mclarke make this only remove the `metadata.managedFields`
61	          replacer: (key: string, value: string): any => {
62	            if (!managedFields) {
63	              return key === 'managedFields' ? undefined : value;
64	            }
65	            return value;
66	          },
67	        })}
68	      />
69	    </>
70	  );
71	};
