18	import { useTheme } from '@material-ui/core/styles';
19	import React from 'react';
20	import type {} from 'react-syntax-highlighter';
21	import LightAsync from 'react-syntax-highlighter/dist/esm/light-async';
22	import dark from 'react-syntax-highlighter/dist/esm/styles/hljs/dark';
23	import docco from 'react-syntax-highlighter/dist/esm/styles/hljs/docco';
24	
25	import { CopyTextButton } from '../CopyTextButton';
26	
27	/**
28	 * Properties for {@link CodeSnippet}
29	 *
30	 * @public
31	 */
32	export interface CodeSnippetProps {
33	  /**
34	   * Code Snippet text
35	   */
36	  text: string;
37	  /**
38	   * Language used by {@link CodeSnippetProps.text}
39	   */
40	  language: string;
41	  /**
42	   * Whether to show line number
43	   *
44	   * @remarks
45	   *
46	   * Default: false
47	   */
48	  showLineNumbers?: boolean;
49	  /**
50	   * Whether to show button to copy code snippet
51	   *
52	   * @remarks
53	   *
54	   * Default: false
55	   */
56	  showCopyCodeButton?: boolean;
57	  /**
58	   * Array of line numbers to highlight
59	   */
60	  highlightedNumbers?: number[];
61	  /**
62	   * Custom styles applied to code
63	   *
64	   * @remarks
65	   *
66	   * Passed to {@link https://react-syntax-highlighter.github.io/react-syntax-highlighter/ | react-syntax-highlighter}
67	   */
68	  customStyle?: any;
69	}
70	
71	/**
72	 * Thin wrapper on top of {@link https://react-syntax-highlighter.github.io/react-syntax-highlighter/ | react-syntax-highlighter}
73	 * providing consistent theming and copy code button
74	 *
75	 * @public
76	 */
77	export function CodeSnippet(props: CodeSnippetProps) {
78	  const {
79	    text,
80	    language,
81	    showLineNumbers = false,
82	    highlightedNumbers,
83	    customStyle,
84	    showCopyCodeButton = false,
85	  } = props;
86	  const theme = useTheme();
87	  const mode = theme.palette.type === 'dark' ? dark : docco;
88	  const highlightColor = theme.palette.type === 'dark' ? '#256bf3' : '#e6ffed';
89	
90	  return (
91	    <Box position="relative">
92	      <LightAsync
93	        customStyle={customStyle}
94	        language={language}
95	        style={mode}
96	        showLineNumbers={showLineNumbers}
97	        wrapLines
98	        lineNumberStyle={{ color: theme.palette.textVerySubtle }}
99	        lineProps={(lineNumber: number) =>
100	          highlightedNumbers?.includes(lineNumber)
101	            ? {
102	                style: {
103	                  backgroundColor: highlightColor,
104	                },
105	              }
106	            : {}
107	        }
108	      >
109	        {text}
110	      </LightAsync>
111	      {showCopyCodeButton && (
112	        <Box position="absolute" top={0} right={0}>
113	          <CopyTextButton text={text} />
114	        </Box>
115	      )}
116	    </Box>
117	  );
118	}
