+        }
+      }
+    },
+    "status": {
+      "$id": "#status",
+      "type": "object",
+      "description": "The current status of the entity, as claimed by various sources.",
+      "required": [],
+      "additionalProperties": true,
+      "properties": {
+        "items": {
+          "type": "array",
+          "items": {
+            "$ref": "#statusItem"
